export function cancelOrder(order) {
  if (order.shipped) throw new Error("already shipped");
  return { ...order, cancelled: true };
}

initialFiles.orders.test.mjs:
import test from "node:test";
import assert from "node:assert/strict";
import { cancelOrder } from "./orders.mjs";
test("cancels unshipped order",()=>assert.equal(cancelOrder({shipped:false}).cancelled,true));
test("rejects shipped order",()=>assert.throws(()=>cancelOrder({shipped:true}),/shipped/));

